import {depthUncertainty,depthUncertaintyExplanation} from './penetration-uncertainty.mjs?v=256072640f6f';
import {penetrationEvidenceMarkup} from './penetration-evidence.mjs?v=256072640f6f';
import {SOIL_DEFAULTS,SOIL_CASES,impactEstimate,missionTelemetry} from './mission-telemetry.mjs?v=256072640f6f';
const tradeNode=id=>document.getElementById(id),tradeNumber=(v,n=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:n}):'—';
let soilInputs={...SOIL_DEFAULTS},tradeChange=()=>{},lastCurve='',lastProbeCount=0;
export function initMissionTradePanel(onChange){tradeChange=onChange;
 const controls=[['impactDiameterM','Effective impact diameter (m)',.02,.1,.001,'Rev09 main body: 0.050 m'],['probeLengthM','Probe length for model warning (m)',.1,.6,.01,'Rev09: 0.200 m'],['impactTiltDeg','Additional impact obliquity (deg)',0,80,1,'Assumed 0°'],...SOIL_CASES.flatMap(x=>[[x.id+'ResistanceMPa',x.name+' effective bearing resistance (MPa)',x.id==='sand'?.01:x.id==='soil'?.2:2,x.id==='sand'?2:x.id==='soil'?20:150,.01,'Assumed; calibration required'],[x.id+'Density',x.name+' density (kg/m³)',800,3000,25,'Assumed; calibration required'],[x.id+'Cd',x.name+' inertial coefficient',0,3,.05,'Assumed; calibration required']])];
 tradeNode('penetrationEvidence').innerHTML=penetrationEvidenceMarkup();
 tradeNode('impactControls').innerHTML=controls.map(([key,label,min,max,step,note])=>`<div class="range-control"><label for="soil-range-${key}">${label}</label><div class="range-pair"><input id="soil-range-${key}" data-soil="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${soilInputs[key]}" aria-label="${label} slider"><input data-soil="${key}" type="number" min="${min}" max="${max}" step="${step}" value="${soilInputs[key]}" aria-label="${label} value"></div><small>${note}</small></div>`).join('');
 tradeNode('impactControls').oninput=e=>{const key=e.target.dataset.soil;if(!key||!e.target.checkValidity())return;soilInputs[key]=Number(e.target.value);for(const input of tradeNode('impactControls').querySelectorAll('input'))if(input.dataset.soil===key&&input!==e.target)input.value=e.target.value;tradeChange();};
 tradeNode('impactDefaults').onclick=()=>{soilInputs={...SOIL_DEFAULTS};for(const input of tradeNode('impactControls').querySelectorAll('input'))input.value=soilInputs[input.dataset.soil];tradeChange();};tradeNode('telemetryProbe').onchange=()=>tradeChange();}
export function getSoilInputs(){return {...soilInputs};}
function metric(label,value,unit='',note=''){return `<div class="live-stat"><span>${label}</span><b>${typeof value==='string'?value:tradeNumber(value)}${unit?' <small>'+unit+'</small>':''}</b>${note?'<small>'+note+'</small>':''}</div>`;}
export function renderMissionReadouts(f,time,c,state,clockLabel='Review synchronized'){if(lastProbeCount!==c.count){lastProbeCount=c.count;tradeNode('telemetryProbe').innerHTML='<option value="auto">Auto · review probe</option>'+Array.from({length:c.count},(_,i)=>`<option value="${i+1}">Probe ${i+1}</option>`).join('');}
 const selected=tradeNode('telemetryProbe').value,probeId=selected==='auto'?(state.event.probe??1):Number(selected),r=missionTelemetry(f,time,c,probeId);
 if(!r){tradeNode('missionTelemetry').innerHTML='<p class="notice">No complete flight solution for these inputs. Adjust the trade inputs; live results are unavailable.</p>';tradeNode('impactLive').innerHTML='';tradeNode('allProbeTelemetry').innerHTML='';tradeNode('impactCurve').innerHTML='';lastCurve='';tradeNode('penetrationEvidence').innerHTML=penetrationEvidenceMarkup();return null;}
 const cap=r.capsule,ca=r.carrier,pr=r.probe,seconds=Math.round(time),h=Math.floor(seconds/3600),m=Math.floor(seconds%3600/60),s=seconds%60;
 tradeNode('liveClock').textContent=`${h} h ${m} m ${s} s · ${clockLabel}`;
 tradeNode('missionTelemetry').innerHTML=metric('Capsule velocity',cap.v,'m/s',cap.status==='discarded'?'Capsule discarded; no later trajectory':cap.status+' · inertial')+metric('Capsule altitude',Number.isFinite(cap.alt)?cap.alt/1000:null,'km')+metric('Capsule load',cap.loadG,'g₀','Thrust / aerodynamic proper acceleration')+metric('Heat shield · center',cap.centerC,'°C',cap.status==='discarded'?'Last value at discard':'Surface estimate')+metric('Heat shield · shoulder',cap.shoulderC,'°C',cap.status==='discarded'?'Last value at discard':'Surface estimate')+metric('Carrier chute · speed',ca.v,'m/s',ca.status)+metric('Carrier chute · altitude',ca.alt,'m')+metric('Carrier drag load',ca.loadG,'g₀')+metric('Probe '+pr.id+' chute · speed',pr.v,'m/s',pr.status)+metric('Probe '+pr.id+' chute · altitude',pr.alt,'m')+metric('Probe chute drag load',pr.loadG,'g₀')+metric('Predicted probe impact speed',pr.predictedImpactV,'m/s','End of complete descent trajectory');
 const active=pr.status!=='stowed',speed=active?Math.abs(pr.vy):0,mode=!active?'Pending probe release':pr.status==='landed'?'At-impact estimates':'Current-speed impact screen';
 tradeNode('impactMode').textContent=`${mode} · Probe ${pr.id} · downward input speed ${active?tradeNumber(speed,2)+' m/s':'—'}. ${pr.status==='descending'?'What if the ground were reached at this instant’s downward speed; the predicted eventual impact speed is shown above.':''}`;
 const estimates=SOIL_CASES.map(x=>({...x,...impactEstimate(speed,c.probeKg,x.id,soilInputs),uncertainty:depthUncertainty(speed,c.probeKg,x.id,soilInputs)}));
 tradeNode('penetrationEvidence').innerHTML=penetrationEvidenceMarkup({massKg:c.probeKg,speedMps:active?speed:null,diameterM:soilInputs.impactDiameterM,estimates});
 tradeNode('impactLive').innerHTML='<table><thead><tr><th>Target</th><th>Peak deceleration (g₀)</th><th>Mean deceleration (g₀)</th><th>Nominal depth (m)</th><th>Assumed 3σ depth interval (m)</th><th>Stopping time (ms)</th></tr></thead><tbody>'+estimates.map(x=>`<tr><th>${x.name}</th><td>${active?tradeNumber(x.peakG,0):'—'}</td><td>${active?tradeNumber(x.meanG,0):'—'}</td><td>${active?tradeNumber(x.depth,3):'—'}${active&&x.beyondLength?' *':''}</td><td>${active?tradeNumber(x.uncertainty.lower,3)+'–'+tradeNumber(x.uncertainty.upper,3):'—'}</td><td>${active?tradeNumber(x.stopSec*1000,2):'—'}</td></tr>`).join('')+'</tbody></table>';
 tradeNode('allProbeTelemetry').innerHTML='<table><thead><tr><th>Probe</th><th>Status</th><th>Altitude (m)</th><th>Current speed (m/s)</th><th>Impact speed (m/s)</th></tr></thead><tbody>'+r.probes.map(x=>`<tr><th>P${x.id}</th><td>${x.status}</td><td>${tradeNumber(x.alt,1)}</td><td>${tradeNumber(x.v,2)}</td><td>${tradeNumber(x.impactV,2)}</td></tr>`).join('')+'</tbody></table>';
 const signature=JSON.stringify([soilInputs,c.probeKg]);if(signature!==lastCurve){lastCurve=signature;tradeNode('impactCurve').innerHTML=impactCurve(c.probeKg);}
 for(const marker of tradeNode('impactCurve').querySelectorAll('.impact-marker')){const x=60+Math.min(200,speed)/200*800;marker.setAttribute('x1',x);marker.setAttribute('x2',x);marker.style.display=active?'':'none';}
 return r;}
function impactCurve(mass){return ['depth','peakG'].map(key=>{const rows=Array.from({length:101},(_,i)=>({v:i*2,cases:SOIL_CASES.map(x=>({...impactEstimate(i*2,mass,x.id,soilInputs),uncertainty:depthUncertainty(i*2,mass,x.id,soilInputs)}))})),max=Math.max(...rows.flatMap(x=>x.cases.map(y=>key==='depth'?y.uncertainty.upper:y[key])))*1.05||1;let svg=`<svg viewBox="0 0 900 230" role="img" aria-label="${key==='depth'?'Penetration depth':'Peak deceleration'} versus downward impact velocity"><text x="60" y="20" fill="#d7e9fa" font-size="15">${key==='depth'?'Penetration (m)':'Peak deceleration (g₀)'} vs downward impact velocity</text>`;for(let j=0;j<=4;j++){const y=180-j*35;svg+=`<path d="M60 ${y} H860" stroke="#33495f"/><text x="52" y="${y+4}" text-anchor="end" fill="#b1c3d7" font-size="12">${tradeNumber(max*j/4,key==='depth'?2:0)}</text>`;}
 SOIL_CASES.forEach((soil,i)=>{if(key==='depth'){const upper=rows.map(x=>`${60+x.v/200*800},${180-x.cases[i].uncertainty.upper/max*140}`),lower=[...rows].reverse().map(x=>`${60+x.v/200*800},${180-x.cases[i].uncertainty.lower/max*140}`);svg+=`<polygon points="${[...upper,...lower].join(' ')}" fill="${soil.color}" fill-opacity="0.16" stroke="none"><title>${soil.name}: assumed 3 sigma interval</title></polygon>`;}svg+=`<polyline points="${rows.map(x=>`${60+x.v/200*800},${180-x.cases[i][key]/max*140}`).join(' ')}" fill="none" stroke="${soil.color}" stroke-width="2.5"/>`;});svg+='<line class="impact-marker" y1="35" y2="185" stroke="white" stroke-dasharray="4 4"/><text x="60" y="210" fill="#b1c3d7">0 m/s</text><text x="860" y="210" text-anchor="end" fill="#b1c3d7">200 m/s</text></svg>';return svg;}).join('')+'<p class="plot-legend">Soft sand · <span style="color:#72dfca">Hard soil</span> · <span style="color:#ccafff">Sandstone</span> · White line: current downward input speed · Shading: assumed 3σ depth interval (depth chart only)</p>'+depthUncertaintyExplanation();}
